    if m == 0 or k >= m or n >= m:
        # If no 20-euro notes, or we have enough initial 10s, or enough 10s
        return "1\n"

    if n < m - k:
        # Not enough 10-euro notes even if all 20s come after all 10s
        return "0\n"

    # We need to count paths from (0, 0) to (n, m) that never have j - i > k
    # where i = # of 10-euro people, j = # of 20-euro people

    # Using the ballot theorem for the case with initial advantage k
    # The formula for valid paths is:
    # sum from i=0 to m-k-1 of (-1)^i * C(n+m, m-i)

    valid_paths = 0
    for i in range(m - k + 1):
        if i % 2 == 0:
            valid_paths += math.comb(n + m, m - i)
        else:
            valid_paths -= math.comb(n + m, m - i)

    total_paths = math.comb(n + m, n)

    probability = valid_paths / total_paths
    return f"{probability:.12f}\n"
