def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Parse costs - A[ij] is cost for city i to build to city j
    costs = [[0]*n for _ in range(n)]
    for i in range(n):
        values = list(map(int, lines[i+1].split()))
        idx = 0
        for j in range(n):
            if j == i:
                continue
            costs[i][j] = values[idx]
            idx += 1

    # Build preference lists (lowest cost = highest preference)
    prefs = []
    for i in range(n):
        pref = sorted(range(n), key=lambda j: costs[i][j])
        prefs.append(pref)

    # Check if pairing is valid
    def is_valid(pairing):
        if any(pairing[i] == i for i in range(n)):
            return False
        for i in range(n):
            if pairing[pairing[i]] != i:
                return False
        return True

    # Check if pairing is stable
    def is_stable(pairing, prefs, costs):
        if not is_valid(pairing):
            return False
        for i in range(n):
            for j in range(i+1, n):
                if pairing[i] == j:
                    continue  # Already paired
                if pairing[j] == i:
                    continue  # Already paired
                # Both would prefer each other than current partner
                i_pref = prefs[i]
                j_pref = prefs[j]
                if pairing[i] != j and i_pref.index(j) < i_pref.index(pairing[i]):
                    if pairing[j] != i and j_pref.index(i) < j_pref.index(pairing[j]):
                        return False
        return True

    # Try to find stable pairing using heuristic search
    import random

    random.seed(42)
    found = None

    if n <= 20 and n % 2 == 0:
        # Try all possible pairings for small n
        def generate_pairings(i, pairing, used):
            if i in used:
                return
            if len(used) == n:
                yield pairing.copy()
                return

            pairing[i] = i
            # Try all unused partners
            for j in range(i+1, n):
                if j not in used:
                    pairing[i] = j
                    pairing[j] = i
                    used.add(i)
                    used.add(j)
                    yield from generate_pairings(i+1, pairing, used)
                    used.discard(i)
                    used.discard(j)
                    pairing[i] = 0

        all_pairings = list(generate_pairings(0, [0]*n, set()))
        for pairing in all_pairings:
            if is_stable(pairing, prefs, costs):
                found = pairing
                break
    else:
        # For larger n, use greedy approach with multiple tries
        for _ in range(min(10000, 2**n.bit_length())):
            pairing = [0]*n
            used = set()

            for i in range(n):
                if i in used:
                    continue
                # Pair with best available
                available = [j for j in range(n) if j not in used]
                if not available:
                    break
                best = available[0]
                pairing[i] = best
                pairing[best] = i
                used.add(i)
                used.add(best)

            if is_valid(pairing) and is_stable(pairing, prefs, costs):
                found = pairing
                break

    if found is None:
        return "-1\n"

    # Output 1-indexed result
    result = []
    for i in range(n):
        result.append(str(found[i] + 1))
    return '\n'.join(result) + '\n'
