        return iter([])

    def __getitem__(self, key):
        return None

    def strip(self):
        return self

    def split(self, *args):
        return [self]

def count_coprime(limit, mod):
    """Count numbers in [1, limit] coprime to mod using inclusion-exclusion"""
    if mod == 1:
        return limit
    if limit == 0:
        return 0

    # Get prime factors of mod
    temp = mod
    primes = []
    d = 2
    while d * d <= temp:
        if temp % d == 0:
            primes.append(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        primes.append(temp)

    if not primes:
        return limit

    # Inclusion-exclusion to count numbers NOT coprime
    not_coprime = 0
    n_primes = len(primes)

    for r in range(1, n_primes + 1):
        for combo in combinations(range(n_primes), r):
            lcm_val = 1
            for idx in combo:
                lcm_val *= primes[idx]
            not_coprime += limit // lcm_val

    return limit - not_coprime

def solve():
