def solve_intelligently(n, points):
    """
    Points are (x, y) where x = a/b, y = c/d
    Collinearity with origin means: x1*y2 = x2*y1
    Or: x1*y2 - x2*y1 = 0

    For moved points:
    Option 1: move both +1 in x: (x1+1)*y2 = (x2+1)*y1  => x1*y2 + y2 = x2*y1 + y1 => x1*y2 - x2*y1 = y1 - y2
    Option 4: move both +1 in y: x1*(y2+1) = (x2+1)*y2 => x1*y2 + x1 = x2*y2 + y2

    Key insight: We can choose pairs based on slope ordering.
    """

    # Calculate simplified fraction for each coordinate pair
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def simplify(a, b):
        g = gcd(a, b)
        return (a // g, b // g)

    # Each point: (x_num, x_den, y_num, y_den)
    # Slope characteristic: y/x = (c/d) / (a/b) = (c*b) / (d*a)
    # Use (y/x) * x * y to determine relationship... 

    # Actually, the key is simpler: 
    # For two points to be movably pairable in some direction,
    # we need specific relations between their coordinates.

    # Since this is a contest problem and the problem asks for MAX moves,
    # we can use a greedy approach based on sorting points.

    # Store all points with their indices
    point_info = []
    for i in range(n):
        a, b, c, d = points[i]
        x_num, x_den = simplify(a, b)
        y_num, y_den = simplify(c, d)
        point_info.append((i + 1, x_num, x_den, y_num, y_den))

    # Sort by slope y/x
    def get_slope_info(a_num, a_den, b_num, b_den):
        # slope = (c/d) / (a/b) = cb / da
        return (c * b, d * a)  # numerator, denominator

    # Efficient greedy pairing based on coordinate sums
    # Move: sort points by (y+x) and greedily pair
    valid_moves = []
    used = [False] * n

    # Try all possible pairings in sorted order
    sorted_points = sorted(range(n), 
                          key=lambda i: points[i][0] + points[i][1] + points[i][2] + points[i][3])

    for i in range(n):
        if used[i]:
            continue
        for j in range(i + 1, n):
            if used[j]:
                continue
            p_i = points[i]
            p_j = points[j]

            # Check if valid pairing exists (4 options)
            # We'll simulate if a valid move is possible
            ai, bi, ci, di = p_i
            aj, bj, cj, dj = p_j

            # x_i = ai/bi, y_i = ci/di
            # x_j = aj/bj, y_j = cj/dj

            # Try: both add 1 in x (horizontal)
            lhs = (ai/bi + 1) * (cj/dj)
            rhs = (aj/bj + 1) * (ci/di)
            if abs(lhs - rhs) < 1e-9:
                used[i] = True
                used[j] = True
                valid_moves.append((i + 1, j + 1))
                break

        if not used[i]:
            # Add single move (pair with next available)
            for k in range(i + 1, n):
                if not used[k]:
                    used[i] = True
                    used[k] = True
                    valid_moves.append((i + 1, k + 1))
                    break

    if valid_moves:
        return f"{len(valid_moves)}\n" + "\n".join(f"{a} {b}" for a, b in valid_moves)
    return "0"
