```python
def solution(input_string):
    lines = input_string.strip().split('\n')
    if len(lines) < 2:
        return "0"

    n, k = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    pairs = []
    for i in range(2, 2 + k):
        if i < len(lines):
            x, y = map(int, lines[i].split())
            pairs.append((x, y))

    # Build chains from special pairs
    prev_node = {}
    next_node = {}
    for x, y in pairs:
        next_node[x] = y
        prev_node[y] = x

    # Build chains starting from nodes with no predecessor in special pairs
    chains = []
    visited = [False] * (n + 1)

    def build_chain(start):
        chain = [start]
        curr = start
        while curr in next_node and next_node[curr] <= n:
            nxt = next_node[curr]
            if not visited[nxt]:
                visited[nxt] = True
                chain.append(nxt)
                curr = nxt
            else:
                break
        return chain

    for node in range(1, n + 1):
        if prev_node.get(node) is None:
            chain = build_chain(node)
            if len(chain) > 0:
                chains.append(chain)

    # Map each node to its chain ID and position within that chain
    chain_pos = {}
    chain_len = {}
    chain_id = 0

    for chain in chains:
        for idx, node in enumerate(chain):
            chain_pos[node] = idx
        chain_len[chain] = len(chain)
        chain_id += 1

    # Build adjacency list for topological sort
    # Include prerequisites + chain constraints
    adj = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)
    added_edges = set()

    # Add prerequisite edges
    for i in range(n):
        if p[i] > 0:
            target = i + 1
            if (p[i], target) not in added_edges:
                adj[p[i]].append(target)
                in_degree[target] += 1
                added_edges.add((p[i], target))

    # Add chain edges (consecutive nodes in chains must be processed in order)
    for chain in chains:
        for i in range(len(chain) - 1):
            u, v = chain[i], chain[i + 1]
            if (u, v) not in added_edges:
                adj[u].append(v)
                in_degree[v] += 1
                added_edges.add((u, v))

    # Topological sort
    from collections import deque
    dq = deque()
    for node in range(1, n + 1):
        if in_degree[node] == 0:
            dq.append(node)

    output = []
    processed = [False] * (n + 1)

    while dq:
        u = dq.popleft()
        processed[u] = True
        output.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                dq.append(v)

    # Verify result
    if len(output) != n:
        return "0"

    # Verify special pairs are consecutive
    for x, y in pairs:
        x_pos = -1
        y_pos = -1
        for i, node in enumerate(output):
            if node == x:
                x_pos = i
            if node == y:
                y_pos = i
        if x_pos == -1 or y_pos == -1 or y_pos - x_pos != 1:
            return "0"

    # Return result
    return ' '.join(map(str, output))
