from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)

    # Compute all-pairs shortest paths using BFS from each node
    all_dist = [[-1] * (n + 1) for _ in range(n + 1)]
    for start in range(1, n + 1):
        dist = [-1] * (n + 1)
        dist[start] = 0
        queue = deque([start])

        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
        all_dist[start] = dist

    best_total = -1
    best_path = None

    # Try all 4 distinct cities
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if all_dist[i][j] == -1:
                continue
            for k in range(j + 1, n + 1):
                if all_dist[j][k] == -1:
                    continue
                for l in range(k + 1, n + 1):
                    if all_dist[k][l] == -1:
                        continue

                    # Found a valid 4-tuple (i, j, k, l) in increasing order
                    # Since we're looking for any optimal solution and the output can be
                    # in any order that works, we check if this path is valid
                    # Actually, we need to consider all permutations
                    # But since we fixed i < j < k < l, we can just test the order
                    total = all_dist[i][j] + all_dist[j][k] + all_dist[k][l]

                    if total > best_total:
                        best_total = total
                        best_path = [i, j, k, l]

    # If no path found with i < j < k < l, try other permutations
    # Actually, the problem might need us to try all permutations
    # But for now, let's try all permutations
    if best_path is None:
        # This shouldn't happen per problem guarantee
        return ' '.join(map(str, range(1, 5)))

    # Try to improve by trying different orderings
    from itertools import permutations

    best_perm_total = -1
    best_perm_path = None

    for perm in permutations(best_path, 4):
        t = all_dist[perm[0]][perm[1]] + all_dist[perm[1]][perm[2]] + all_dist[perm[2]][perm[3]]
        if t > best_perm_total:
            best_perm_total = t
            best_perm_path = list(perm)

    # Return the best path found
    if best_perm_path is None or best_perm_total == -1:
        # Fallback - should not happen per problem guarantee
        return f"{best_path[0]} {best_path[1]} {best_path[2]} {best_path[3] if best_path else 4}"

