import os

MOD = 1000000007

def cross_product(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def on_segment(p, a, b):
    return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and \
           min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

def segments_intersect(a, b, c, d):
    """Check if segment ab strictly intersects segment cd"""
    d1 = cross_product(c[0], c[1], a[0], a[1])
    d2 = cross_product(c[0], c[1], b[0], b[1])
    d3 = cross_product(a[0], a[1], c[0], c[1])
    d4 = cross_product(a[0], a[1], d[0], d[1])

    if ((d1 > 0 and d2 < 0 and d3 > 0 and d4 < 0) or 
        (d1 < 0 and d2 > 0 and d3 < 0 and d4 > 0)):
        return True

    if d1 == 0 and on_segment(a, c, d):
        return True
    if d2 == 0 and on_segment(b, c, d):
        return True
    if d3 == 0 and on_segment(c, a, b):
        return True
    if d4 == 0 and on_segment(d, a, b):
        return True

    return False

def is_valid_diagonal(i, j, n, points):
    if abs(i - j) <= 1:
        return False

    for k in range(n):
        nk = (k + 1) % n
        if k == i or nk == i or k == j or nk == j:
            continue
        if segments_intersect(points[i], points[j], points[k], points[nk]):
            return False
    return True

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(n):
        x, y = map(int, lines[1+i].split())
        points.append((x, y))

    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n):
            j = (i + length - 1) % n
            if length == 2:
                dp[i][j] = 1
            else:
                cnt = 0
                for k in range(i + 1, i + length - 1):
                    k_idx = k % n
                    if is_valid_diagonal(i, k_idx, n, points) and is_valid_diagonal(k_idx, j, n, points):
                        cnt = (cnt + dp[i][k_idx] * dp[k_idx][j]) % MOD
                dp[i][j] = cnt

    return str(dp[0][0] if n > 0 else 0)

