Let me write a clean solution using binary search for each segment:

```python
import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    points = []
    for i in range(1, n + 2):
        coords = list(map(int, lines[i].split()))
        points.append(tuple(float(c) for c in coords))

    vp_int, vs_int = map(int, lines[n + 2].split())
    px, py, pz = map(int, lines[n + 3].split())

    vp = float(vp_int)
    vs = float(vs_int)
    H = (float(px), float(py), float(pz))

    def dist(p1, p2):
        return math.sqrt((p1[0]-p2[0])**2 + (p1[1]-p2[1])**2 + (p1[2]-p2[2])**2)

    # Calculate segment lengths and times
    segment_lengths = [dist(points[i], points[i+1]) for i in range(n)]
    segment_times = [l / vs for l in segment_lengths]
    cumulative_times = [0.0]
    for t in segment_times:
        cumulative_times.append(cumulative_times[-1] + t)

    def snitch_pos(time):
        """Return position of snitch at time"""
        for i, end_time in enumerate(cumulative_times):
            if time <= end_time + 1e-9:
                seg_idx = i
                break
        else:
            return points[n]

        seg_len = segment_lengths[seg_idx]
        seg_duration = seg_len / vs
        t_in_segment = min(time, cumulative_times[seg_idx])

        start_p = points[seg_idx]
        end_p = points[seg_idx+1]

        if seg_duration == 0:
            factor = 0.0
        else:
            factor = t_in_segment / seg_duration

        return (start_p[0] + factor * (end_p[0] - start_p[0]),
                start_p[1] + factor * (end_p[1] - start_p[1]),
                start_p[2] + factor * (end_p[2] - start_p[2]))

    def check_pos_at_time(time):
        """Check if Harry can catch snitch at time t"""
        sp = snitch_pos(time)
        d = dist(H, sp)
        return d <= vp * time + 1e-9

    # Check all segment endpoints first
    found_time = None
    found_pos = None

    for i in range(n + 1):
        t = cumulative_times[i]
        sp = snitch_pos(t)
        d = dist(H, sp)
        if d <= vp * t + 1e-9:
            found_time = t
            found_pos = sp
            break

    if found_time is not None:
        pos = (round(found_pos[0], 12), round(found_pos[1], 12), round(found_pos[2], 12))
        return f"YES\n{found_time:.12f}\n{pos[0]:.12f} {pos[1]:.12f} {pos[2]:.12f}"

    # Binary search within each segment
    for i in range(n):
        t_left = cumulative_times[i]
        t_right = cumulative_times[i+1]

        if t_left == t_right:
            continue

        # Binary search
        lo, hi = t_left, t_right
        for _ in range(60):
            mid = (lo + hi) / 2
            if check_pos_at_time(mid):
                hi = mid
            else:
                lo = mid

        if check_pos_at_time(hi):
            found_time = hi
            found_pos = snitch_pos(hi)
            break

    if found_time is not None:
        pos = (round(found_pos[0], 12), round(found_pos[1], 12), round(found_pos[2], 12))
        return f"YES\n{found_time:.12f}\n{pos[0]:.12f} {pos[1]:.12f} {pos[2]:.12f}"

    return "NO"
