import sys

MOD = 1000003

def parse_cell_type(cell):
    if cell == '1':
        return (1, 1)  # x=0, y=1
    elif cell == '2':
        return (1, 0)  # x=0, y=0
    elif cell == '3':
        return (0, 1)  # x=1, y=1
    elif cell == '4':
        return (0, 0)  # x=1, y=0
    return None  # for '.'

def process_cell(row, col, val):
    """
    Determine required s_x(col) and s_y(row) based on pipe type
    Returns: (sx_req, sy_req)
    sx_req: required s_x for this column
    sy_req: required s_y for this row
    """
    # val is (x_i_j, y_i_j) where x_i_j and y_i_j are the actual required values
    # s_x(col) determines x(i,col): if i is even, x = s_x, if i is odd, x = 1-s_x
    # s_y(row) determines y(row,j): if j is even, y = s_y, if j is odd, y = 1-s_y

    i = row
    j = col

    # Required x value at this cell
    x_req = val[0]
    # Required y value at this cell  
    y_req = val[1]

    # For x: x(i,j) = s_x(j) if i%2==0 else 1-s_x(j)
    # So s_x(j) = x_req if i%2==0 else 1-x_req
    if i % 2 == 0:
        sx = x_req
    else:
        sx = 1 - x_req

    # For y: y(i,j) = s_y(i) if j%2==0 else 1-s_y(i)
    # So s_y(i) = y_req if j%2==0 else 1-y_req
    if j % 2 == 0:
        sy = y_req
    else:
        sy = 1 - y_req

    return (sx, sy)

def count_configurations(n, m, grid):
    # For each column, track required s_x values
    col_constraints = {}  # col -> required s_x value (or None if no constraint)
    # For each row, track required s_y values
    row_constraints = {}  # row -> required s_y value (or None if no constraint)

    possible = True

    for i in range(n):
        for j in range(m):
            cell = grid[i][j]
            if cell == '.':
                continue

            # Parse type
            pipe_types = {'1': (1, 1), '2': (1, 0), '3': (0, 1), '4': (0, 0)}
            val = pipe_types[cell]

            sx_sy = process_cell(i, j, val)

            # Check column constraint
            if j in col_constraints:
                if col_constraints[j] is None:
                    col_constraints[j] = sx_sy[0]
                elif col_constraints[j] != sx_sy[0]:
                    possible = False
