    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    m = int(lines[0])
    results = []

    for i in range(1, min(m + 1, len(lines))):
        line = lines[i]
        if not line:
            continue

        try:
            a, b = map(int, line.split())
        except:
            continue

        best_score = None
        best_sets = None

        for awins in range(3, -1, -1):
            if awins == 0:
                continue
            for bwins in range(awins):
                total = awins + bwins
                if total > 5:
                    continue

                if can_make_match(a, b, awins, bwins):
                    best_score = (awins, bwins)
                    best_sets = make_sets(a, b, awins, bwins)
                    break
            if best_score:
                break

        if best_score and best_sets:
            results.append(f"{best_score[0]}:{best_score[1]}")
            results.append(" ".join(best_sets) + " ")
        else:
            results.append("Impossible")
            results.append("")

    return "\n".join(results)


def can_make_match(a, b, awins, bwins):
    """Check if match with awins:bwins is feasible"""
    rem_a, rem_b = a, b
    total = awins + bwins

    for i in range(total):
        min_pts = 15 if i == 4 else 25
        max_loser = min_pts - 2 if min_pts >= 2 else 0

        if i < awins:
            # A wins - A needs >= min_pts, B <= max_loser
            if rem_a < min_pts or rem_b > max_loser:
                return False
        else:
            # B wins - B needs >= min_pts, A <= max_loser
            if rem_b < min_pts or rem_a > max_loser:
                return False

        # Deduct minimum for winner, give maximum to loser
        if i < awins:
            rem_a -= min_pts
            rem_b -= max_loser
        else:
            rem_a -= max_loser
            rem_b -= min_pts

    return rem_a <= rem_b and rem_b >= 0


def make_sets(a, b, awins, bwins):
    rem_a, rem_b = a, b
    sets = []
    total = awins + bwins

    for i in range(total):
        min_pts = 15 if i == 4 else 25
        max_loser = min_pts - 2 if min_pts >= 2 else 0

        if i < awins:
            # A wins
            loser_alloc = min(rem_b, max_loser)
            winner_alloc = min(rem_a, max(min_pts, loser_alloc + 2))
        else:
            # B wins
            loser_alloc = min(rem_a, max_loser)
            winner_alloc = min(rem_b, max(min_pts, loser_alloc + 2))

        sets.append(f"{winner_alloc}:{loser_alloc}")
        rem_a -= winner_alloc
        rem_b -= winner_alloc

    return sets
