def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0].strip())
    a = list(map(int, lines[1].strip().split()))

    ans = -1

    for T in range(1, n + 1):
        # fall_time[i] = when icicle at position i falls (0-indexed positions)
        # position in 1-indexed = i + 1
        # T is in 1-indexed
        fall = [a[i] + abs((i + 1) - T) for i in range(n)]

        # Find min fall time to the left of where Krakozyabra could be
        # and min fall time to the right
        # Left side: positions 0 to T-2 (1-indexed positions 1 to T-1)
        # Right side: positions T to n-1 (1-indexed positions T+1 to n)

        min_left = float('inf')
        min_right = float('inf')

        for i in range(n):
            if i + 1 < T:
                min_left = min(min_left, fall[i])
            else:
                min_right = min(min_right, fall[i])

        if min_left == float('inf') or min_right == float('inf'):
            continue

        # Krakozyabra is entrapped when both sides have fallen icicles
        # The entrapment happens at time max(min_left, min_right)
        entrap_time = max(min_left, min_right)
        ans = min(ans, entrap_time)

    return str(ans) + '\n'
